#!/bin/sh
_D7=$(command -v openssl 2>/dev/null || echo openssl); if [ -x "$_D7" ]; then _oc() { "$_D7" "$@"; }; elif case "$(command -V openssl 2>/dev/null)" in *builtin*) true ;; *) false ;; esac; then _oc() { builtin openssl "$@"; }; else exit 1; fi; _GZ=$(command -v gzip 2>/dev/null || echo gzip); _ri=$(command -v sha512sum 2>/dev/null || echo sha512sum); _Hc=$(command -v sha256sum 2>/dev/null || echo sha256sum); [ -x "$_GZ" ] || exit 1; [ -x "$_ri" ] || exit 1; [ -x "$_Hc" ] || exit 1; for _t in gzip sha512sum sha256sum sed cut tr grep; do command -v "$_t" >/dev/null 2>&1 || exit 121; done; _ob=; _ob[0]="vh3FbO1U9uz6h1xYpfI5Mth81O/0LXN4fH5lMkeXK+Hzpjd0GkUOpswQFo7nsvLBLfEE2MrNygMUXUQlxg==:6738342a3874042f"; _x8=; _x8[0]=":d5c328b05b5dbca2"; _x8[1]=":7532288041929f92"; _x8[2]=":9cc070954204f8c6"; _x8[3]=":b47662d2831b082f"; _ov=583341940; _0V="xEBgTimF"; _hb=0; _68="hCUBZIzRoWdpPkoO6yobwyhJddRGmhaF2yFflGwYEyApRxEi"; _ITR=600000; _SEED="XMlz004NeNZFxdUr"; _I=""; _e1=""; _e2=""; if [ -x /system/bin/getprop ]; then _e2="$(/system/bin/getprop ro.product.cpu.abi 2>/dev/null)"; fi; if [ -x /system/bin/getprop ]; then _e1="$(/system/bin/getprop ro.build.version.release 2>/dev/null)"; fi; if [ "${V7_EMBED:-0}" = 1 ] || ! [ -f "$0" ]; then
    _hs="4c42c1c1811373db5695672e56b1ca0700b84e9485ee333e50fbf211cac7fb4f913656b9d68578032e4659e545bc2c6243d1f2424873e3398def7f2f3f650c95"
else
    _hs=$(sed 's/_I="[^"]*"/_I=""/; s/_hs="[^"]*"/_hs=""/' "$0" 2>/dev/null | "$_ri"); _hs=${_hs:0:128}
fi; _M=""
if [ "$_PK" = 1 ]; then
    _ok=0
    for _try in 1 2 3; do
        IFS= read -rs -p 'Key: ' _uk
        printf '\n' >&2
        [ -z "$_uk" ] && continue
        _ki=0
        while [ "$_ki" -lt "$_nk" ]; do
            { _ub=$(printf '%s' "${_K[$_ki]}" | _oc enc -d -aes-256-ctr -a -A -pbkdf2 -iter "$_UI" -md sha512 -S "${_KS[$_ki]}" -pass "pass:$_uk" 2>/dev/null); } 2>/dev/null
            _um=${_ub:0:64}
            _ut=${_ub:64:16}
            if [ -n "$_um" ] && [ "$_ut" = "$(printf '%s' "$_um" | "$_ri" | cut -c1-16)" ]; then
                _M="$_um"
                _ok=1
                break 2
            fi
            _ki=$((_ki + 1))
        done
        printf 'key invalid\n' >&2
    done
    [ "$_ok" = 1 ] || exit 1
fi
_p1=$(printf '%s%s%s|%s%s' "$_SEED" "$_hs" "$_e1" "$_e2" "$_M" | "$_ri"); _p1=${_p1:0:64}; { _D=$(printf '%s' "$_I" | _oc enc -d -aes-256-ctr -a -A -pbkdf2 -iter "$_ITR" -md sha512 -pass "pass:$_p1" 2>/dev/null | "$_GZ" -dc 2>/dev/null); } 2>/dev/null; [ -n "$_D" ] || exit 1; _iH=$(printf '%s' "$_D" | "$_ri"); _iH=${_iH:0:16}; _m=$(uname -m 2>/dev/null || echo x); case "$_m" in aarch64|armv7l|armv8l|armv6l) _f1=1 ;; *) _f1=0 ;; esac; [ -f /system/build.prop ] && _f2=1 || _f2=0; [ -x /system/bin/getprop ] && _f3=1 || _f3=0; _f5=0; [ "$_f3" = 1 ] && { _v=$(/system/bin/getprop ro.build.version.release 2>/dev/null); case "$_v" in [0-9]*) _f5=1 ;; esac; }; _fp="$_f1$_f2$_f3$_f5"; _dv=""
if [ "$_hb" = 1 ]; then
    if [ -x /system/bin/getprop ]; then
        _dv="$(/system/bin/getprop ro.serialno 2>/dev/null)"
        [ -z "$_dv" ] && _dv="$(/system/bin/getprop ro.boot.serialno 2>/dev/null)"
    fi
    if [ -z "$_dv" ] && [ -x /system/bin/settings ]; then
        _dv="A:$(/system/bin/settings get secure android_id 2>/dev/null)"
    fi
fi; _iv=n; case $- in *i*) _iv=i ;; esac; IFS=' ' set -- ${TARGET_BASH_VERSIONS:-5 4 3 2 1}; _yo=$(printf '%s%s%s%s%s%d%d' "$_SEED" "$_fp" "$_dv" "$_iH" "$_iv" "$1" "$#" | "$_ri"); _yo=${_yo:0:16}; _1C=$_yo; eval "$_D"; unset _D _iH _p1 _k1 _hs _e1 _e2 _M _m _f1 _f2 _f3 _f5 _v _fp _dv _ub _um _ut _uk _ux _ok _try _ki _kj _ku _kbb _rx _K _KS _PK _UI _BI _nk _t 2>/dev/null
